--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `id` int NOT NULL AUTO_INCREMENT,
  `order_token` varchar(20) DEFAULT NULL,
  `weekmenu_id` int NOT NULL,
  `user_id` int DEFAULT NULL,
  `group_id` int DEFAULT NULL,
  `quantity` int NOT NULL DEFAULT '0',
  `special_price` decimal(10,2) DEFAULT NULL,
  `spicy` int NOT NULL DEFAULT '0',
  `week` int NOT NULL DEFAULT '0',
  `year` int NOT NULL DEFAULT '0',
  `notes` mediumtext,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `weekmenu_id` (`weekmenu_id`),
  KEY `order_token_user_id` (`order_token`,`user_id`),
  KEY `FK_orders_groups` (`group_id`),
  CONSTRAINT `FK_orders_groups` FOREIGN KEY (`group_id`) REFERENCES `groups` (`id`) ON DELETE SET NULL ON UPDATE SET NULL,
  CONSTRAINT `orders_ibfk_1` FOREIGN KEY (`weekmenu_id`) REFERENCES `weekmenu` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=18737 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

