DROP TABLE IF EXISTS `weekmenu`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `weekmenu` (
  `id` int NOT NULL AUTO_INCREMENT,
  `week` int NOT NULL,
  `year` int NOT NULL,
  `group_id` int DEFAULT NULL,
  `menu_id` int NOT NULL,
  `quantity` int NOT NULL DEFAULT '0',
  `ordering` int NOT NULL DEFAULT '0',
  `invitation` int NOT NULL DEFAULT '0',
  `delivered_on` date DEFAULT NULL,
  `token` varchar(50) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `menu_id` (`menu_id`),
  KEY `week_year` (`week`,`year`),
  KEY `FK_weekmenu_groups` (`group_id`),
  CONSTRAINT `FK_weekmenu_groups` FOREIGN KEY (`group_id`) REFERENCES `groups` (`id`) ON DELETE SET NULL ON UPDATE SET NULL,
  CONSTRAINT `weekmenu_ibfk_1` FOREIGN KEY (`menu_id`) REFERENCES `menu` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3195 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

